-- Audited backup and two-person restore jobs.
insert into storage.buckets(id,name,public) values('cms-backups','cms-backups',false) on conflict(id) do update set public=false;
create table if not exists public.cms_backup_jobs(id uuid primary key default gen_random_uuid(),job_type text not null check(job_type in('backup','restore')),source_environment text not null check(source_environment in('staging','production')),target_environment text check(target_environment in('staging','production')),source_backup_id uuid references public.cms_backup_jobs(id),status text not null check(status in('pending','pending_approval','approved','running','completed','failed','cancelled')),requested_by uuid not null references auth.users(id),approved_by uuid references auth.users(id),requested_at timestamptz not null default now(),approved_at timestamptz,started_at timestamptz,completed_at timestamptz,artifact_key text,artifact_sha256 text,artifact_bytes bigint,error_message text,evidence jsonb not null default '{}');
alter table public.cms_backup_jobs enable row level security;grant select on public.cms_backup_jobs to authenticated;create policy "CMS reads backup jobs" on public.cms_backup_jobs for select to authenticated using(public.cms_current_role() in('super_admin','reviewer'));
create or replace function public.cms_request_backup(p_environment text) returns public.cms_backup_jobs language plpgsql security definer set search_path=public as $$ declare v public.cms_backup_jobs;begin if public.cms_current_role()<>'super_admin' then raise exception 'permission_denied';end if;if p_environment not in('staging','production')then raise exception 'invalid_environment';end if;insert into public.cms_backup_jobs(job_type,source_environment,status,requested_by)values('backup',p_environment,'pending',auth.uid())returning * into v;insert into public.cms_audit_logs(actor_id,action,resource_type,resource_id,metadata)values(auth.uid(),'backup_requested','backup_job',v.id::text,jsonb_build_object('environment',p_environment));return v;end $$;
create or replace function public.cms_request_restore(p_backup_id uuid,p_target_environment text) returns public.cms_backup_jobs language plpgsql security definer set search_path=public as $$ declare v public.cms_backup_jobs;begin if public.cms_current_role()<>'super_admin' then raise exception 'permission_denied';end if;if p_target_environment not in('staging','production')then raise exception 'invalid_environment';end if;if not exists(select 1 from public.cms_backup_jobs where id=p_backup_id and job_type='backup' and status='completed' and artifact_sha256 is not null)then raise exception 'verified_backup_required';end if;insert into public.cms_backup_jobs(job_type,source_environment,target_environment,source_backup_id,status,requested_by)select'restore',source_environment,p_target_environment,id,'pending_approval',auth.uid() from public.cms_backup_jobs where id=p_backup_id returning * into v;insert into public.cms_audit_logs(actor_id,action,resource_type,resource_id,metadata)values(auth.uid(),'restore_requested','backup_job',v.id::text,jsonb_build_object('backup_id',p_backup_id,'target',p_target_environment));return v;end $$;
create or replace function public.cms_approve_restore(p_job_id uuid) returns void language plpgsql security definer set search_path=public as $$ declare v_requester uuid;begin if public.cms_current_role() not in('super_admin','reviewer')then raise exception 'permission_denied';end if;select requested_by into v_requester from public.cms_backup_jobs where id=p_job_id and job_type='restore' and status='pending_approval' for update;if not found then raise exception 'restore_not_pending';end if;if v_requester=auth.uid()then raise exception 'self_approval_forbidden';end if;update public.cms_backup_jobs set status='approved',approved_by=auth.uid(),approved_at=now()where id=p_job_id;insert into public.cms_audit_logs(actor_id,action,resource_type,resource_id,metadata)values(auth.uid(),'restore_approved','backup_job',p_job_id::text,'{}');end $$;
create or replace function public.cms_record_backup_job(p_job_id uuid,p_status text,p_artifact_key text default null,p_sha256 text default null,p_bytes bigint default null,p_error text default null,p_evidence jsonb default '{}')returns void language plpgsql security definer set search_path=public as $$ begin if auth.role()<>'service_role'then raise exception 'service_role_required';end if;if p_status not in('running','completed','failed')then raise exception 'invalid_job_status';end if;update public.cms_backup_jobs set status=p_status,started_at=case when p_status='running'then now()else started_at end,completed_at=case when p_status in('completed','failed')then now()else null end,artifact_key=coalesce(p_artifact_key,artifact_key),artifact_sha256=coalesce(p_sha256,artifact_sha256),artifact_bytes=coalesce(p_bytes,artifact_bytes),error_message=left(p_error,500),evidence=coalesce(p_evidence,'{}') where id=p_job_id and ((job_type='backup'and status in('pending','running'))or(job_type='restore'and status in('approved','running')));if not found then raise exception 'job_not_mutable';end if;end $$;
revoke execute on function public.cms_request_backup(text),public.cms_request_restore(uuid,text),public.cms_approve_restore(uuid),public.cms_record_backup_job(uuid,text,text,text,bigint,text,jsonb) from public,anon;grant execute on function public.cms_request_backup(text),public.cms_request_restore(uuid,text),public.cms_approve_restore(uuid) to authenticated;grant execute on function public.cms_record_backup_job(uuid,text,text,text,bigint,text,jsonb) to service_role;
